const menu=document.querySelector('.menu'),navigation=document.querySelector('#navigation');
menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));navigation.classList.toggle('open',expanded)});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');navigation.classList.remove('open')}));
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#service').value=a.dataset.service}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('.work-grid').classList.toggle('filtered',button.dataset.filter!=='all');let visible=0;document.querySelectorAll('.project-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.group!==button.dataset.filter;if(!card.hidden)visible++});document.querySelector('#project-count').textContent=`${visible} selected website${visible===1?'':'s'}`;}));
const projects=JSON.parse(document.querySelector('#projects-data').textContent),dialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects.find(p=>p.id===button.dataset.project);document.querySelector('#dialog-title').textContent=p.name;document.querySelector('#dialog-category').textContent=p.category+' / '+p.status;document.querySelector('#dialog-description').textContent=p.details;document.querySelector('#dialog-note').textContent=p.note;document.querySelector('#dialog-features').replaceChildren(...p.features.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));document.querySelector('#dialog-image').src=`assets/${p.id}.webp`;document.querySelector('#dialog-image').alt=`${p.name} website preview`;document.querySelector('#dialog-link').href=p.url;dialog.showModal();document.body.classList.add('locked')}));
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('locked'));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#enquiry').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target),body=`Hello Afeez,\n\n${f.get('message')}\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nBusiness / website: ${f.get('business')||'Not supplied'}\nHelp needed: ${f.get('service')}\nBudget: ${f.get('budget')}\n`;location.href=`mailto:info@afeezdev.tech?subject=${encodeURIComponent('Website project enquiry — '+f.get('service'))}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Your email app should open with a draft. If it doesn’t, email info@afeezdev.tech directly.';});
